<?php $usos=$usos??[];$origenUsos=!empty($maestro)?$baseCatalogo.'/editar?id='.$id:$baseArticulos.'/editar?id='.$id; ?>
<details class="admin-panel admin-card m2-disclosure" id="usos"><summary>Dónde se utiliza</summary><p class="admin-field__hint">Referencias guardadas, incluidas versiones anteriores, dentro de tu acceso. Hasta 20 por sección; consultar no modifica composiciones.</p>
<?php $hayUsos=false;foreach(['elaboraciones'=>'Elaboraciones publicadas','presentaciones'=>'Presentaciones','recetas'=>'Recetas comerciales anteriores','variantes'=>'Ajustes de variantes','anteriores'=>'Preparaciones anteriores','asociaciones'=>'Asociaciones físicas'] as $tipo=>$titulo):$items=$usos[$tipo]??[];if(!$items)continue;$hayUsos=true; ?><h3><?= $titulo ?></h3><?php if(in_array($tipo,['presentaciones','recetas'],true)): ?><p class="admin-field__hint">La versión indica la referencia guardada. El enlace abre la configuración actual del producto o presentación.</p><?php endif; ?><ul>
<?php foreach(array_slice($items,0,20) as $uso):$urlUso=null;if($tipo==='elaboraciones')$urlUso=$baseArticulos.'/editar?'.http_build_query(['id'=>$uso['articulo_id'],'version'=>$uso['id'],'volver'=>$origenUsos]);elseif($tipo==='presentaciones')$urlUso=($ctx==='restaurante'?'/admin':'/admin/'.$ctx).'/menu/presentaciones?'.http_build_query(['id'=>$uso['oferta_id'],'presentacion'=>$uso['id'],'volver'=>$origenUsos]);elseif($tipo==='variantes')$urlUso=($ctx==='restaurante'?'/admin':'/admin/'.$ctx).'/menu/variantes?'.http_build_query(['id'=>$uso['oferta_id'],'volver'=>$origenUsos]);elseif($tipo==='recetas')$urlUso=($ctx==='restaurante'?'/admin':'/admin/'.$ctx).'/recetas/editar?'.http_build_query(['id'=>$uso['oferta_id'],'volver'=>$origenUsos]);elseif($tipo==='asociaciones')$urlUso=$baseAlmacenes.'?'.http_build_query(['almacen_id'=>$uso['id'],'articulo_id'=>$id,'volver'=>$origenUsos]); ?>
<li><?php if($urlUso): ?><a href="<?= $esc($urlUso) ?>"><?php endif; ?><?= $esc($uso['nombre']) ?><?php if(isset($uso['slug'])): ?> · <?= $esc(\Services\Security\Contextos::NOMBRES[$uso['slug']]??$uso['slug']) ?><?php endif; ?><?php if(isset($uso['version'])): ?> · Versión <?= (int)$uso['version'] ?><?php endif; ?><?php if($urlUso): ?></a><?php endif; ?></li><?php endforeach; ?></ul><?php if(count($items)>20): ?><p class="admin-field__hint">Hay más referencias. Consulta el módulo correspondiente para ampliar la búsqueda.</p><?php endif; ?><?php endforeach; ?>
